export default function UserStats({ users }: UserStatsProps) {
  // Derived values calculated directly
  const activeUsersCount = users.filter(user => user.isActive).length;
  const inactiveUsersCount = users.length - activeUsersCount;
  const activePercentage = users.length > 0 
    ? (activeUsersCount / users.length) * 100 
    : 0;

  return (
    <div>
      <h2>User Statistics</h2>
      <ul>
        <li>Active Users: {activeUsersCount}</li>
        <li>Inactive Users: {inactiveUsersCount}</li>
        <li>Active Percentage: {activePercentage.toFixed(1)}%</li>
      </ul>
    </div>
  );
}

